actions.script:
// a site's theme preview host (Commerce P5, F54): only the preview render and its assets, every other path Not Found
const previewer=ec.resource.script('component://mr-pass/screen/Shop/ShopPreview.js')
if(previewer.isPreviewHost(siteId,hostname)){const previewRoute=previewer.route(path);screenPath=previewRoute.screenPath;screenParameters=previewRoute.screenParameters}
else{
const info=ec.service.sync().throwOnError(true).name('pass.Facade.call#Operation').parameters({operation:'getSiteInfo',input:{siteId,hostname}}).call().result
const mounted=info.mounts.filter(m=>path===m.pathPrefix || path.startsWith((m.pathPrefix==='/'?'':m.pathPrefix)+'/')).sort((a,b)=>b.pathPrefix.length-a.pathPrefix.length)[0]
const fail=()=>{const error=new Error('Page not found');error.moquiErrorKind='NotFound';throw error}
if(!mounted || path.includes('..'))fail()
const root=ec.resource.script('component://mr-pass/service/pass/Apps.js')[mounted.app]?.screen
if(!root)fail()
const suffix=path.slice(mounted.pathPrefix==='/'?0:mounted.pathPrefix.length)
const parts=suffix.split('/').filter(Boolean)
if(mounted.app==='forum' && parts[0]==='t'){
    if(!/^[A-Za-z0-9_-]{1,40}$/.test(parts[1] || ''))fail()
    topicId=parts[1];const mode=(parts[2] || '').match(/\.(qvue|qvt|qjs)$/);topicSlug=(parts[2] || '').replace(/\.(qvue|qvt|qjs)$/,'');screenPath='/Forum/Topics/TopicDetail'+(mode?'.'+mode[1]:'')+(parts.length>3?'/'+parts.slice(3).join('/'):'')
}else if(mounted.app==='forum' && parts[0]==='p'){
    if(!/^[A-Za-z0-9_-]{1,40}$/.test(parts[1] || ''))fail()
    postId=parts[1];screenPath='/Forum/Post'
}else if(mounted.app==='shop' && ['products','categories','pages'].includes(parts[0])){
    // Shop's canonical paths (impl-shop P1; design-shop §11): a stable id and a decorative slug, or a page's
    // path; the page reads them from publicPath
    const id=/^[A-Za-z0-9_-]{1,40}$/,slug=/^[A-Za-z0-9_-]{0,200}$/
    if(parts[0]==='pages'){if(parts.length<2 || parts.length>6 || !parts.slice(1).every(p=>id.test(p)))fail();screenPath='/Shop/Page';screenParameters={routePath:parts.slice(1).join('/')}}
    else{if(!id.test(parts[1] || '') || parts.length>3 || !slug.test(parts[2] || ''))fail()
        // P3: the id and the slug as screen parameters (F47); the page redirects an old slug after its access check
        if(parts[0]==='products'){screenPath='/Shop/Products/ProductDetail';screenParameters={productId:parts[1],productSlug:parts[2] || ''}}
        else{screenPath='/Shop/Categories/CategoryDetail';screenParameters={productCategoryId:parts[1],categorySlug:parts[2] || ''}}}
}else if(mounted.app==='shop' && parts.length===1 && ['robots.txt','sitemap.xml'].includes(parts[0])){
    // P3: the Shop's robots and sitemap (design-shop §11: only current public pages)
    screenPath=parts[0]==='robots.txt'?'/Shop/robots':'/Shop/sitemap'
}else if(mounted.app==='shop' && parts[0]==='theme'){
    // a theme release's asset (impl-shop P2): theme/{the release's manifest digest}/{path under assets/}
    const name=/^[A-Za-z0-9_-][A-Za-z0-9_.-]{0,100}$/
    if(!/^[0-9a-f]{64}$/.test(parts[1] || '') || parts.length<3 || parts.length>8 || !parts.slice(2).every(p=>name.test(p)))fail()
    screenPath='/Shop/themeAsset';screenParameters={themeDigest:parts[1],assetPath:parts.slice(2).join('/')}
}else screenPath='/'+root+suffix
}
